# Let's define a function to parse expenses from a note content
import re

def parse_expenses_from_content(content):
    pattern = r'-\s+(\w+)\s+paid\s+\$(\d+(?:\.\d+)?)\s+for\s+"([^"]+)"\.\s+Owed equally by\s+(.+)\.'
    matches = re.findall(pattern, content)
    expenses = []
    for payer, amount, desc, debtors_str in matches:
        # Split debtors by comma or "and"
        debtors = re.split(r',\s*|\s+and\s+', debtors_str)
        debtors = [d.strip() for d in debtors if d.strip()]
        expenses.append({
            'payer': payer,
            'amount': float(amount),
            'description': desc,
            'debtors': debtors
        })
    return expenses

# Parse all four notes
